<?php
require_once '../includes/config.php'; require_permission('manage_staff'); $pdo=db();
$labels=['manage_site'=>'Manage Site','products'=>'Products','inventory'=>'Inventory','orders'=>'Orders','support'=>'Customer support'];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('danger','Enter a valid name/email and password of at least 8 characters.');redirect('team.php');}try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,'staff',1)");$st->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO staff_permissions(user_id,permission_key,allowed) VALUES(?,?,1)');foreach(array_intersect(array_keys($labels),$_POST['permissions']??[]) as $perm)$ins->execute([$id,$perm]);$pdo->commit();flash('success','Staff account created with the selected permissions.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Could not create account; email may already be in use.');}redirect('team.php');}
$title='Add Staff';require '../includes/header.php';?>
<div class="row justify-content-center"><div class="col-lg-9"><div class="bg-white border rounded-4 p-4 p-lg-5"><span class="badge text-bg-light mb-2">LIMITED STAFF ACCESS</span><h1 class="section-title">Add a staff member</h1><p class="text-secondary">Your account can create a staff login because an administrator granted this permission. You cannot grant the staff-management permission or create administrator accounts.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="name" required maxlength="120"></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" name="email" type="email" required maxlength="190"></div><div class="col-12"><label class="form-label">Temporary password (8+ characters)</label><input class="form-control" name="password" type="password" minlength="8" required autocomplete="new-password"></div></div><hr><h5>Assign available permissions</h5><label class="form-check mb-2"><input class="form-check-input staff-select-all" type="checkbox"> <span class="form-check-label fw-semibold">All permissions available to me</span></label><div class="row g-2"><?php foreach($labels as $key=>$label):?><div class="col-sm-6"><label class="border rounded-3 p-3 d-flex gap-2 align-items-center"><input class="form-check-input mt-0" type="checkbox" name="permissions[]" value="<?=e($key)?>"><span><?=e($label)?></span></label></div><?php endforeach;?></div><div class="d-flex gap-2 mt-4"><button class="btn btn-purple">Create staff account</button><a href="index.php" class="btn btn-light">Cancel</a></div></form></div></div></div>
<script>
document.querySelectorAll('.staff-select-all').forEach(master=>master.addEventListener('change',()=>{const form=master.closest('form');form?.querySelectorAll('input[name="permissions[]"]').forEach(box=>box.checked=master.checked);}));
</script>
